def plan(pid, title, thesis, context, b1, b2, alt, concl, cards, points):
    return {"id": pid, "title": title,
            "notes": [{"key": "Thesis: " + thesis}, {"h": "Context"}, {"p": context},
                      {"h": "Body 1: " + b1[0]}, {"list": b1[1]}, {"h": "Body 2: " + b2[0]}, {"list": b2[1]},
                      {"h": "Alternative perspective"}, {"p": alt}, {"h": "Conclusion"}, {"p": concl}],
            "dump": [{"p": "Write the full outline from memory: thesis, three context sentences, both body paragraphs with their evidence and analysis, the counterargument with your answer, and the conclusion."}],
            "cards": cards, "points": points}

